(* [comment removed for export] *)
Lemma body_count : forall (es : list mbe) (insz n : Z) (k hl C : Z) (x : Z),
  mb_ok es insz -> 1 <= n -> 0 <= insz -> insz + n <= 2^26 -> 0 <= hl ->
