  as_RFS H ((1, ff, fp) :: LF) m1 -> Forall (fs_scratch H ((1, ff, fp) :: LF)) XS' -> aceil <= SP -> SP <= a ->
  Forall (fun iv : Z * Z => a + n <= fst iv \/ snd iv <= a) Xc ->
  xclient_range H LBx SP (Xc ++ XS') a n.
Proof.
  intros LBx SP Xc XS' m1 a n RF FXS CE LE FXc. split; [left; exact LE|]. apply Forall_app. split; [exact FXc|].
  exact (proj2 (scratch_xclient_stack H HH LBx _ m1 XS' SP a n RF FXS CE LE)).
Qed.

(* [comment removed for export] *)
Lemma xcl_frame : forall LBx (SP : Z) Xc XS' (m1 : mem) a n,
  as_RFS H ((1, ff, fp) :: LF) m1 -> Forall (fs_scratch H ((1, ff, fp) :: LF)) XS' -> ff <= a -> a + n <= ff + 128 -> 0 <= n ->
  Forall (fun iv : Z * Z => a + n <= fst iv \/ snd iv <= a) Xc ->
  xclient_range H LBx SP (Xc ++ XS') a n.
Proof.
  open_X. intros LBx SP Xc XS' m1 a n RF FXS L1 L2 N0 FXc. split; [eapply (ff_client_range H); [exact FF| exact L1| rewrite fsz_1; exact L2]|].
  apply Forall_app. split; [exact FXc|].
  exact (live_frame_off_scratch H HH _ _ _ _ _ _ a n RF FXS L1 ltac:(rewrite fsz_1; exact L2) N0).
Qed.

Lemma xcl_row : forall LBx (SP : Z) Xc XS' (m1 : mem),
  as_RFS H ((1, ff, fp) :: LF) m1 -> Forall (fs_scratch H ((1, ff, fp) :: LF)) XS' ->
  Forall (fun iv : Z * Z => sh ff + 16 <= fst iv \/ snd iv <= sh ff) Xc ->
  xclient_range H LBx SP (Xc ++ XS') (sh ff) 16.
Proof.
  open_X. intros LBx SP Xc XS' m1 RF FXS FXc.
  pose proof (frame_facts H MX CX X XOK) as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & SHFF & _).
  split; [eapply (ffsh_client_range H); [exact FF| rewrite SHFF; lia| rewrite SHFF, fshn_1; lia]|].
  apply Forall_app. split; [exact FXc|].
  pose proof (live_shadow_off_scratch H HH _ _ _ _ _ _ RF FXS) as K. rewrite fshn_1 in K. exact K.
Qed.

Lemma xcl_flag : forall LBx (SP : Z) Xc XS' (m1 : mem),
  as_RFS H ((1, ff, fp) :: LF) m1 -> Forall (fs_scratch H ((1, ff, fp) :: LF)) XS' ->
  Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) Xc ->
  xclient_range H LBx SP (Xc ++ XS') fp 1.
Proof.
  open_X. intros LBx SP Xc XS' m1 RF FXS FXc. split; [eapply (fp_client_range H); exact FF|].
  apply Forall_app. split; [exact FXc|]. exact (live_flag_off_scratch H HH _ _ _ _ _ _ RF FXS).
Qed.

(* [comment removed for export] *)
Lemma win_sub : forall m p k, bytes_at bsegs m p0 bs -> p0 <= p -> 0 <= k -> p + k <= p1 ->
  bytes_at bsegs m p (firstn (Z.to_nat k) (skipn (Z.to_nat (p - p0)) bs)) /\ zlength (firstn (Z.to_nat k) (skipn (Z.to_nat (p - p0)) bs)) = k.
Proof.
  intros m p k W H1 H2 H3. unfold X8_BP_put4.p1 in H3. pose proof W as (_ & _ & _).
  pose proof (bytes_at_sub m p0 bs (Z.to_nat (p - p0)) (Z.to_nat k) W ltac:(lia)) as W1.
  rewrite Z2Nat.id in W1 by lia. replace (p0 + (p - p0)) with p in W1 by lia. split; [exact W1|].
  unfold zlength. rewrite length_firstn, length_skipn. lia.
Qed.

